            try: err = r.json()
            except Exception: err = {"error": r.text[:300]}
            raise ValueError(f"{r.status_code}: {err.get('error')} {err.get('detail', '')}".strip())
        m, p = rcb1.decode(r.content); return Result(m, p, self._spec)

